def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
      - Multiplos de 3 son 'Fizz'
      - Multiplos de 5 son 'Buzz'
      - Multiplos de 3 y 5 son 'FizzBuzz'
      - Los demás son los números como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos usando notación sustractiva."""
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    romanos = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result = []
    for value, symbol in romanos:
        while n >= value:
            result.append(symbol)
            n -= value

    return "".join(result)

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == max_elemento:
            longitud += 1
        else:
            if longitud > max_racha:
                max_racha = longitud
                max_elemento = lista[i]
                longitud = 1

    if longitud > max_racha:
        max_racha = longitud
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minúscula y las siguientes con la inicial en mayúscula,
    sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(word) == 1:
                result.append(word)
            else:
                result.append(word[0].upper() + word[1:])
    return " ".join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: El texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.

    Un texto vacío es considerado balanceado.
    """
    if not s:
        return True

    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in mapping:
            stack.append(char)
        elif char in mapping.values():
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False
        else:
            stack.append(char)

    return len(stack) == 0

def transpuesta(m):
    if not m:
        return []
    rows = len(m)
    cols = len(m[0])
    transpuesta = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            transpuesta[j][i] = m[i][j]
    return transpuesta

def anidar(plano: dict) -> dict:
    """
    Recorre un diccionario plano y crea un diccionario anidado
    donde cada clave con puntos se convierte en un diccionario
    con la misma clave y el valor del valor original.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            key_parts = key.split('.')
            current = result
            for part in key_parts[:-1]:
                current = current.setdefault(part, {})
            current[key_parts[-1]] = value
        else:
            result[key] = value
    return result

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024.

    Unidades: B, KB, MB, GB.
    B va sin decimales, KB, MB, GB van con decimales.

    Args:
        n: Número entero en bytes.

    Returns:
        String formateada como 'X.B' o 'X.KB' o 'X.MB' o 'X.GB'.
    """
    if n <= 0:
        return "0 B"

    if n <= 1024:
        return f"{n} B"
    elif n <= 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n <= 1024 * 1024 * 1024:
        return f"{n / 1024 / 1024:.1f} MB"
    else:
        return f"{n / 1024 / 1024 / 1024:.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

